contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint minSum, uint lockTime, uint putValue, uint collectAmount) public payable {
        require(address(this).balance >= putValue);

        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1));
        c.Initialized();
        c.Put{value: putValue}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        bool locked = block.timestamp <= unlockTimeBefore;
        bool insufficientOrExcessive = balanceBefore < minSum || balanceBefore < collectAmount;
        bool shouldRevertCollect = locked || insufficientOrExcessive;

        if (shouldRevertCollect) {
            assert(reverted && balanceAfter == balanceBefore);
        } else {
            assert(!reverted && balanceAfter == balanceBefore - collectAmount);
        }
    }

    receive() external payable {}
}

