    function run(uint _am, uint _lockTime, uint _minSum) public payable {
        require(_lockTime > 0, "lockTime");

        // Set up a LogFile so that successful Collect can call Log.AddMessage.
        c.SetLogFile(LOG_ADDR);

        // Set MinSum to a parameter so we can vary the boundary.
        c.SetMinSum(_minSum);

        // Deposit some value with a lock time; balance and unlockTime change.
        uint deposit = _am;
        require(address(this).balance >= deposit, "balance");
        c.Put{value: deposit}(_lockTime);

        uint minSumBefore = c.MinSum();
        (uint unlockTime, uint balance) = c.Acc(address(this));

        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        bool hasLog = true;
        bool enoughBalance = balance >= _am;
        bool enoughMinSum = balance >= minSumBefore;
        bool unlocked = block.timestamp > unlockTime;

        bool shouldSucceed = hasLog && enoughBalance && enoughMinSum && unlocked;

        assert(reverted == !shouldSucceed);
    }

    receive() external payable {}
}

